import { reticle } from '../reticle-singleton.js';
export function createReticleEmitter(options = {}) {
    const target = options.target ?? reticle;
    return {
        signal(name, data = {}) {
            if (!target.connected)
                return;
            target.signal(name, data);
        },
        state(name, value) {
            if (!target.connected)
                return;
            target.state(name, value);
        },
    };
}
